//! The bridge's claim leaf (simf/claim.simf) over stock Elements jets, and a local harness that runs it.
//!
//! A claim mints any one unclaimed deposit of the Ethereum escrow's SHA-256 accumulator (BridgeDeposits.sol)
//! without any SNARK: the accumulator is committed in the Liquid state, which only the SP1 update leaf advances.
//! The state also commits the claimed tree (`ClaimedTree`), one slot per deposit index, and a claim sets exactly
//! the slot of the deposit it mints. That update leaf is generated by tools/sg16/bridge-guest/liquid.py; here it is
//! known only by its CMR, the claim leaf's sibling in the state tree.
//!
//! The harness runs over upstream `ElementsEnv`; it is not a node. It checks the control-block commitment and
//! Elements amount proofs; it does not validate fee-input signatures or provide a chain-backed UTXO set.

use crate::crypto::{pair, require, sha, Result, Root};

use simplicity::{
    elements::{
        self,
        confidential::{Asset, AssetBlindingFactor, Nonce, Value, ValueBlindingFactor},
        encode::serialize,
        hashes::{sha256, Hash},
        secp256k1_zkp::{
            Generator, PedersenCommitment, Secp256k1, SecretKey, SurjectionProof, Tweak,
            XOnlyPublicKey, ZERO_TWEAK,
        },
        taproot::{ControlBlock, LeafVersion, TapLeafHash, TaprootBuilder, TaprootSpendInfo},
        AssetId, AssetIssuance, LockTime, OutPoint, Script, Transaction, TxIn, TxOut, Txid,
    },
    jet::{
        elements::{ElementsEnv, ElementsUtxo},
        Elements,
    },
    BitIter, BitMachine, Cmr, RedeemNode,
};
use simplicityhl::{
    ast::ElementsJetHinter, num::U256, types::TypeConstructible, value::ValueConstructible,
    Arguments, CompiledProgram, ResolvedType, TemplateProgramWitness, Value as HlValue,
    WitnessNameToValueMap, WitnessValues,
};
use std::{
    collections::{BTreeMap, BTreeSet, HashMap},
    sync::Arc,
};

/// BIP341's NUMS point: no known discrete logarithm, so no key-path spend.
pub const NUMS: &str = "50929b74c1a04954b78b4b6035e97a5e078a5a0f28ec96d547bfee9ace803ac0";

/// Depth of the escrow's deposit tree, and of the claimed tree beside it.
pub const TREE_DEPTH: usize = 32;

/// Preimage of the state leaf's domain tag.
pub const STATE_TAG: &[u8] = b"liquid-bridge-poc/state";

/// Preimage of the value of a set slot in the claimed tree.
pub const CLAIMED_TAG: &[u8] = b"liquid-bridge-poc/claimed";

/// Preimages of the two public token blinding factors, each hashed with the asset entropy.
pub const TOKEN_BLINDING_TAGS: [&[u8]; 2] = [
    b"liquid-bridge-poc/token-blinding/A",
    b"liquid-bridge-poc/token-blinding/B",
];

/// SHA256(STATE_TAG): the first word of every state hash.
pub fn state_tag() -> Root {
    sha(STATE_TAG)
}

/// SHA256(CLAIMED_TAG): slot i of the claimed tree once deposit i is minted; 0 before.
pub fn claimed_leaf() -> Root {
    sha(CLAIMED_TAG)
}

/// SHA256(SHA256(STATE_TAG) || lc || acc || claimed_root); the state leaf's "CMR".
pub fn state_hash(s: &State) -> Root {
    sha(&[&state_tag()[..], &s.lc, &s.acc, &s.claimed_root].concat())
}

/// SHA256(DOMAIN || be64(index) || be64(units) || recipient), as BridgeDeposits.leafOf.
pub fn deposit_leaf(domain: Root, index: u64, units: u64, recipient: Root) -> Root {
    sha(&[
        &domain[..],
        &index.to_be_bytes(),
        &units.to_be_bytes(),
        &recipient,
    ]
    .concat())
}

/// SHA256(treeRoot || be64(count)), the escrow's storage slot 0.
pub fn accumulator(root: Root, count: u64) -> Root {
    sha(&[&root[..], &count.to_be_bytes()].concat())
}

/// The public token blinding factor of `phase` (0 for A, 1 for B) for the asset of `entropy`.
pub fn token_blinding(entropy: Root, phase: usize) -> Root {
    sha(&[TOKEN_BLINDING_TAGS[phase], &entropy[..]].concat())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct State {
    /// Commitment to the Ethereum light-client store; defined by the update leaf, opaque here.
    pub lc: Root,
    /// Escrow accumulator proven at the store's finalized execution block.
    pub acc: Root,
    /// Root of the claimed tree: which deposits are already minted.
    pub claimed_root: Root,
}

/// The roots of empty subtrees by height: 0 at the leaves, then SHA256(z || z). The empty deposit tree and the
/// empty claimed tree share them.
pub fn empty_roots() -> [Root; TREE_DEPTH + 1] {
    let mut zero = [[0; 32]; TREE_DEPTH + 1];
    for h in 0..TREE_DEPTH {
        zero[h + 1] = pair(zero[h], zero[h]);
    }
    zero
}

/// Append-only depth-32 SHA-256 tree, the same construction as BridgeDeposits.sol.
#[derive(Clone, Debug)]
pub struct DepositTree {
    pub domain: Root,
    pub deposits: Vec<(u64, Root)>,
    zero: [Root; TREE_DEPTH + 1],
}

impl DepositTree {
    pub fn new(domain: Root) -> Self {
        Self {
            domain,
            deposits: vec![],
            zero: empty_roots(),
        }
    }

    pub fn push(&mut self, units: u64, recipient: Root) -> u64 {
        self.deposits.push((units, recipient));
        self.deposits.len() as u64 - 1
    }

    pub fn count(&self) -> u64 {
        self.deposits.len() as u64
    }

    pub fn leaf(&self, index: u64) -> Root {
        let (units, recipient) = self.deposits[index as usize];
        deposit_leaf(self.domain, index, units, recipient)
    }

    fn levels(&self) -> Vec<Vec<Root>> {
        let mut levels = vec![(0..self.count()).map(|i| self.leaf(i)).collect::<Vec<_>>()];
        for h in 0..TREE_DEPTH {
            let level = &levels[h];
            let next = (0..level.len().div_ceil(2))
                .map(|j| pair(level[2 * j], *level.get(2 * j + 1).unwrap_or(&self.zero[h])))
                .collect();
            levels.push(next);
        }
        levels
    }

    pub fn root(&self) -> Root {
        *self.levels()[TREE_DEPTH]
            .first()
            .unwrap_or(&self.zero[TREE_DEPTH])
    }

    pub fn accumulator(&self) -> Root {
        accumulator(self.root(), self.count())
    }

    pub fn branch(&self, index: u64) -> [Root; TREE_DEPTH] {
        let levels = self.levels();
        let mut out = [[0; 32]; TREE_DEPTH];
        for (h, sibling) in out.iter_mut().enumerate() {
            let at = ((index >> h) ^ 1) as usize;
            *sibling = *levels[h].get(at).unwrap_or(&self.zero[h]);
        }
        out
    }
}

/// The rule the claim leaf applies: bit h of the index is 0 when the node is the left child.
pub fn root_from_branch(leaf: Root, index: u64, branch: &[Root; TREE_DEPTH]) -> Root {
    let mut node = leaf;
    for (h, sibling) in branch.iter().enumerate() {
        node = if (index >> h) & 1 == 0 {
            pair(node, *sibling)
        } else {
            pair(*sibling, node)
        };
    }
    node
}

/// The claimed tree: a depth-32 SHA-256 sparse Merkle tree over deposit indices, shaped like the deposit tree, whose
/// slot i is `claimed_leaf()` once deposit i is minted and 0 before. Its root, the state's `claimed_root`, depends
/// only on the set of claimed indices, not on the order they were claimed in. A slot is opened under a root by
/// `root_from_branch` with the slot's value as the leaf.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ClaimedTree {
    indices: BTreeSet<u64>,
}

impl ClaimedTree {
    /// Nothing claimed: the initial state's tree.
    pub fn new() -> Self {
        Self::default()
    }

    pub fn contains(&self, index: u64) -> bool {
        self.indices.contains(&index)
    }

    /// Number of deposits claimed.
    pub fn len(&self) -> u64 {
        self.indices.len() as u64
    }

    pub fn is_empty(&self) -> bool {
        self.indices.is_empty()
    }

    /// This tree with slot `index` set. Panics if `index` is outside the tree, which holds indices below 2^32.
    pub fn with(&self, index: u64) -> Self {
        assert!(index < 1 << TREE_DEPTH, "claimed index outside the tree");
        let mut next = self.clone();
        next.indices.insert(index);
        next
    }

    /// The non-empty nodes by height: level h maps the index of each node with a set slot below it to its hash.
    fn levels(&self) -> Vec<BTreeMap<u64, Root>> {
        let zero = empty_roots();
        let mut levels = vec![self
            .indices
            .iter()
            .map(|&i| (i, claimed_leaf()))
            .collect::<BTreeMap<_, _>>()];
        for h in 0..TREE_DEPTH {
            let level = &levels[h];
            let node = |j: u64| *level.get(&j).unwrap_or(&zero[h]);
            let parents = level.keys().map(|&j| j >> 1).collect::<BTreeSet<_>>();
            let next = parents
                .into_iter()
                .map(|j| (j, pair(node(2 * j), node(2 * j + 1))))
                .collect();
            levels.push(next);
        }
        levels
    }

    pub fn root(&self) -> Root {
        *self.levels()[TREE_DEPTH]
            .get(&0)
            .unwrap_or(&empty_roots()[TREE_DEPTH])
    }

    /// The 32 siblings of slot `index`, bottom up, as the claim leaf's CLAIMED_PATH takes them.
    pub fn branch(&self, index: u64) -> [Root; TREE_DEPTH] {
        let zero = empty_roots();
        let levels = self.levels();
        let mut out = [[0; 32]; TREE_DEPTH];
        for (h, sibling) in out.iter_mut().enumerate() {
            *sibling = *levels[h].get(&((index >> h) ^ 1)).unwrap_or(&zero[h]);
        }
        out
    }
}

/// The claimed root with exactly deposits 0..count minted, computed without the tree. A state whose accumulator
/// opens to `count` deposits has nothing left to claim exactly when its `claimed_root` is this: the root binds the
/// set, and a claim sets only slots below the count. Panics if `count` exceeds the tree.
pub fn complete_root(count: u64) -> Root {
    assert!(
        count <= 1 << TREE_DEPTH,
        "more deposits than the tree holds"
    );
    let zero = empty_roots();
    let mut full = [claimed_leaf(); TREE_DEPTH + 1];
    for h in 0..TREE_DEPTH {
        full[h + 1] = pair(full[h], full[h]);
    }
    // The root of a height-h subtree whose first n slots are set and the rest unset.
    fn prefix(n: u64, h: usize, full: &[Root], zero: &[Root]) -> Root {
        if n == 0 {
            return zero[h];
        }
        if n == 1 << h {
            return full[h];
        }
        let half = 1 << (h - 1);
        if n <= half {
            pair(prefix(n, h - 1, full, zero), zero[h - 1])
        } else {
            pair(full[h - 1], prefix(n - half, h - 1, full, zero))
        }
    }
    prefix(count, TREE_DEPTH, &full, &zero)
}

/// Policy constants compiled into the claim leaf.
#[derive(Clone, Debug)]
pub struct Params {
    pub liquid_genesis: Root,
    /// Issuance entropy of the bridge asset, fixed by the bootstrap outpoint.
    pub entropy: Root,
    pub fee_asset: AssetId,
    /// BridgeDeposits.DOMAIN of the deployed escrow.
    pub deposit_domain: Root,
    /// Public asset blinding factors of the token in alternate states.
    pub token_blinding: [Root; 2],
}

fn secp() -> Secp256k1<elements::secp256k1_zkp::All> {
    Secp256k1::new()
}

impl Params {
    pub fn asset(&self) -> AssetId {
        AssetId::from_entropy(sha256::Midstate::from_byte_array(self.entropy))
    }

    pub fn token(&self) -> AssetId {
        AssetId::reissuance_token_from_entropy(
            sha256::Midstate::from_byte_array(self.entropy),
            false,
        )
    }

    pub fn token_asset(&self, phase: usize) -> Asset {
        Asset::new_confidential(
            &secp(),
            self.token(),
            AssetBlindingFactor::from_slice(&self.token_blinding[phase]).unwrap(),
        )
    }

    /// 1 * H(token): constant in every state, because the value blinding is minus the asset blinding.
    pub fn token_value(&self) -> Value {
        let gen = Generator::new_unblinded(&secp(), self.token().into_tag());
        Value::Confidential(PedersenCommitment::new_unblinded(&secp(), 1, gen))
    }
}

pub fn leaf_version() -> LeafVersion {
    LeafVersion::from_u8(0xbe).unwrap()
}

fn nums() -> XOnlyPublicKey {
    XOnlyPublicKey::from_slice(&hex::decode(NUMS).unwrap()).unwrap()
}

fn lit(x: &[u8]) -> String {
    format!("0x{}", hex::encode(x))
}

/// (odd-y bit, x) of a serialized 33-byte commitment, as the Simplicity jets expose it.
fn point(serialized: &[u8]) -> (String, String) {
    assert_eq!(serialized.len(), 33);
    ((serialized[0] & 1).to_string(), lit(&serialized[1..]))
}

/// The claim leaf's source for `p`: simf/claim.simf with every parameter replaced by its literal. A manifest
/// records the SHA-256 of this text (`claim_leaf.source_sha256`) beside the CMR it compiles to.
pub fn source(p: &Params) -> String {
    let (a_parity, a_x) = point(&serialize(&p.token_asset(0)));
    let (b_parity, b_x) = point(&serialize(&p.token_asset(1)));
    let (v_parity, v_x) = point(&serialize(&p.token_value()));
    let asset = serialize(&Asset::Explicit(p.asset()));
    let fee_asset = serialize(&Asset::Explicit(p.fee_asset));
    let src = include_str!("../simf/claim.simf")
        .replace("param::STATE_TAG", &lit(&state_tag()))
        .replace("param::NUMS", &format!("0x{NUMS}"))
        .replace("param::TOKEN_A_PARITY", &a_parity)
        .replace("param::TOKEN_A_X", &a_x)
        .replace("param::TOKEN_B_PARITY", &b_parity)
        .replace("param::TOKEN_B_X", &b_x)
        .replace("param::TOKEN_VALUE_PARITY", &v_parity)
        .replace("param::TOKEN_VALUE_X", &v_x)
        .replace("param::ENTROPY", &lit(&p.entropy))
        .replace("param::BRIDGE_ASSET", &lit(&asset[1..]))
        .replace("param::FEE_ASSET", &lit(&fee_asset[1..]))
        .replace("param::DEPOSIT_DOMAIN", &lit(&p.deposit_domain))
        .replace("param::CLAIMED_LEAF", &lit(&claimed_leaf()));
    assert!(!src.contains("param::"), "unreplaced parameter");
    src
}

/// The claim leaf compiled for `p`.
pub fn compile(p: &Params) -> std::result::Result<CompiledProgram, String> {
    CompiledProgram::new(
        source(p),
        Arguments::default(),
        false,
        Box::new(ElementsJetHinter::new()),
    )
}

/// A bridge instance as the claim leaf sees it: the compiled claim leaf, and the update leaf beside it by CMR
/// alone.
pub struct Bridge {
    pub params: Params,
    pub claim: CompiledProgram,
    pub claim_cmr: Cmr,
    /// CMR of the update leaf in the state tree: on Liquid, the generated SP1 update leaf a manifest names.
    pub update_cmr: Root,
}

impl Bridge {
    pub fn new(params: Params, update_cmr: Root) -> std::result::Result<Self, String> {
        let claim = compile(&params)?;
        let claim_cmr = claim.commit().cmr();
        Ok(Self {
            params,
            claim,
            claim_cmr,
            update_cmr,
        })
    }

    /// P2TR(NUMS, {{update, claim}, state}).
    pub fn state_info(&self, s: &State) -> TaprootSpendInfo {
        let leaf = |cmr: &[u8]| Script::from(cmr.to_vec());
        TaprootBuilder::new()
            .add_leaf_with_ver(2, leaf(&self.update_cmr), leaf_version())
            .unwrap()
            .add_leaf_with_ver(2, leaf(self.claim_cmr.as_ref()), leaf_version())
            .unwrap()
            .add_leaf_with_ver(1, leaf(&state_hash(s)), leaf_version())
            .unwrap()
            .finalize(&secp(), nums())
            .unwrap()
    }

    pub fn state_script(&self, s: &State) -> Script {
        Script::new_v1_p2tr_tweaked(self.state_info(s).output_key())
    }

    /// The control block of state `s` for the leaf whose script is `leaf` (the claim or the update CMR).
    pub fn control(&self, s: &State, leaf: &[u8]) -> ControlBlock {
        self.state_info(s)
            .control_block(&(Script::from(leaf.to_vec()), leaf_version()))
            .unwrap()
    }

    /// The update leaf's hash: the first element of the claim leaf's taproot path.
    pub fn sibling(&self) -> Root {
        TapLeafHash::from_script(&Script::from(self.update_cmr.to_vec()), leaf_version())
            .to_byte_array()
    }
}

/// One claim spend: the transaction, its spent outputs and the witness of input 0.
#[derive(Clone, Debug)]
pub struct Spend {
    pub tx: Transaction,
    pub spent: Vec<TxOut>,
    pub old: State,
    pub new: State,
    pub control: ControlBlock,
    pub witness: HashMap<&'static str, HlValue>,
}

pub fn u256(x: Root) -> HlValue {
    HlValue::u256(U256::from_byte_array(x))
}

pub fn u64_value(x: u64) -> HlValue {
    HlValue::u64(x)
}

pub fn path_value(branch: &[Root; TREE_DEPTH]) -> HlValue {
    HlValue::array(branch.iter().map(|x| u256(*x)), ResolvedType::u256())
}

fn explicit(asset: AssetId, value: u64, script: Script) -> TxOut {
    TxOut {
        asset: Asset::Explicit(asset),
        value: Value::Explicit(value),
        nonce: Nonce::Null,
        script_pubkey: script,
        witness: Default::default(),
    }
}

pub fn p2tr(key: Root) -> Script {
    Script::from([&[0x51, 0x20][..], &key].concat())
}

/// The output scripts BridgeDeposits.recipientOf accepts, so the ones the claim leaf can pay: P2PKH, P2SH,
/// P2WPKH, P2WSH, and P2TR with a valid x-only key.
pub fn is_standard_recipient(s: &[u8]) -> bool {
    match s.len() {
        25 => s[..3] == [0x76, 0xa9, 0x14] && s[23..] == [0x88, 0xac],
        23 => s[..2] == [0xa9, 0x14] && s[22] == 0x87,
        22 => s[..2] == [0x00, 0x14],
        34 => {
            s[..2] == [0x00, 0x20]
                || (s[..2] == [0x51, 0x20] && XOnlyPublicKey::from_slice(&s[2..]).is_ok())
        }
        _ => false,
    }
}

pub fn fee_input(id: u8) -> OutPoint {
    OutPoint::new(Txid::from_byte_array([id; 32]), 0)
}

impl Bridge {
    fn token_input(&self, s: &State, phase: usize) -> TxOut {
        TxOut {
            asset: self.params.token_asset(phase),
            value: self.params.token_value(),
            nonce: Nonce::Null,
            script_pubkey: self.state_script(s),
            witness: Default::default(),
        }
    }

    /// Output 0 with the other phase's commitments, a surjection proof over `domain` and a range proof.
    fn successor(
        &self,
        s: &State,
        next_phase: usize,
        domain: &[(Generator, elements::secp256k1_zkp::Tag, Tweak)],
    ) -> TxOut {
        let p = &self.params;
        let bf = p.token_blinding[next_phase];
        let mut out = TxOut {
            asset: p.token_asset(next_phase),
            value: p.token_value(),
            nonce: Nonce::Null,
            script_pubkey: self.state_script(s),
            witness: Default::default(),
        };
        let mut rng = elements::secp256k1_zkp::rand::thread_rng();
        out.witness.surjection_proof = Some(Box::new(
            SurjectionProof::new(
                &secp(),
                &mut rng,
                p.token().into_tag(),
                Tweak::from_slice(&bf).unwrap(),
                domain,
            )
            .unwrap(),
        ));
        let vbf = ValueBlindingFactor::from_slice(
            &SecretKey::from_slice(&bf).unwrap().negate().secret_bytes(),
        )
        .unwrap();
        let msg = elements::RangeProofMessage {
            asset: p.token(),
            bf: AssetBlindingFactor::from_slice(&bf).unwrap(),
        };
        let (value, range) = Value::Explicit(1)
            .blind_with_shared_secret(
                &secp(),
                vbf,
                SecretKey::from_slice(&[9; 32]).unwrap(),
                &out.script_pubkey,
                &msg,
            )
            .unwrap();
        assert_eq!(value, out.value, "constant token value commitment");
        out.witness.rangeproof = Some(Box::new(range));
        out
    }

    fn token_domain(&self, phase: usize) -> (Generator, elements::secp256k1_zkp::Tag, Tweak) {
        (
            self.params.token_asset(phase).commitment().unwrap(),
            self.params.token().into_tag(),
            Tweak::from_slice(&self.params.token_blinding[phase]).unwrap(),
        )
    }

    fn explicit_domain(&self, asset: AssetId) -> (Generator, elements::secp256k1_zkp::Tag, Tweak) {
        (
            Generator::new_unblinded(&secp(), asset.into_tag()),
            asset.into_tag(),
            ZERO_TWEAK,
        )
    }

    /// The one-time funding transaction: input 0 spends `funding` (explicit fee asset, `value`) and newly issues one
    /// reissuance token and no asset; output 0 is the first state UTXO holding the token with blinding A, output 1
    /// the fee. `funding` must be the outpoint the entropy was derived from. Its own signature is not produced here;
    /// anyone can check the result before use.
    pub fn bootstrap(
        &self,
        funding: OutPoint,
        value: u64,
        initial: &State,
    ) -> (Transaction, Vec<TxOut>) {
        let p = &self.params;
        let mut input = TxIn {
            previous_output: funding,
            ..TxIn::default()
        };
        input.asset_issuance = AssetIssuance {
            asset_blinding_nonce: ZERO_TWEAK,
            asset_entropy: [0; 32],
            amount: Value::Null,
            inflation_keys: Value::Explicit(1),
        };
        let domain = [
            self.explicit_domain(p.fee_asset),
            self.explicit_domain(p.token()),
        ];
        let tx = Transaction {
            version: 2,
            lock_time: LockTime::ZERO,
            input: vec![input],
            output: vec![
                self.successor(initial, 0, &domain),
                explicit(p.fee_asset, value, Script::new()),
            ],
        };
        (tx, vec![explicit(p.fee_asset, value, Script::new())])
    }

    /// Mint deposit `index` of `tree`, whose accumulator must be `old.acc`, to output script `script`; the
    /// deposit's recipient is SHA256 of the script it is to be paid to. `claimed` is the old state's claimed tree.
    /// The spend is built even if slot `index` is already set, so that tests can show the leaf refuses it. Panics
    /// if `index` is not a deposit of `tree` or `claimed` is not the tree of `old`; test fixtures only.
    #[allow(clippy::too_many_arguments)]
    pub fn claim(
        &self,
        old: &State,
        claimed: &ClaimedTree,
        index: u64,
        phase: usize,
        prev: OutPoint,
        tree: &DepositTree,
        fee: u64,
        script: Script,
    ) -> Spend {
        let p = &self.params;
        assert_eq!(
            claimed.root(),
            old.claimed_root,
            "claimed tree of the old state"
        );
        let (units, recipient) = tree.deposits[index as usize];
        let new = State {
            claimed_root: claimed.with(index).root(),
            ..*old
        };

        let mut input0 = TxIn {
            previous_output: prev,
            ..TxIn::default()
        };
        input0.asset_issuance = AssetIssuance {
            asset_blinding_nonce: Tweak::from_slice(&p.token_blinding[phase]).unwrap(),
            asset_entropy: p.entropy,
            amount: Value::Explicit(units),
            inflation_keys: Value::Null,
        };
        let input1 = TxIn {
            previous_output: fee_input(15),
            ..TxIn::default()
        };
        let domain = [
            self.token_domain(phase),
            self.explicit_domain(p.asset()),
            self.explicit_domain(p.fee_asset),
        ];
        let tx = Transaction {
            version: 2,
            lock_time: LockTime::ZERO,
            input: vec![input0, input1],
            output: vec![
                self.successor(&new, 1 - phase, &domain),
                explicit(p.asset(), units, script),
                explicit(p.fee_asset, fee, Script::new()),
            ],
        };

        let mut witness = HashMap::new();
        witness.insert("LC", u256(old.lc));
        witness.insert("ACC", u256(old.acc));
        witness.insert("CLAIMED_ROOT", u256(old.claimed_root));
        witness.insert("SIBLING", u256(self.sibling()));
        witness.insert("TREE_ROOT", u256(tree.root()));
        witness.insert("COUNT", u64_value(tree.count()));
        witness.insert("INDEX", u64_value(index));
        witness.insert("RECIPIENT", u256(recipient));
        witness.insert("PATH", path_value(&tree.branch(index)));
        witness.insert("CLAIMED_PATH", path_value(&claimed.branch(index)));
        Spend {
            tx,
            spent: vec![
                self.token_input(old, phase),
                explicit(p.fee_asset, fee, Script::new()),
            ],
            old: *old,
            new,
            control: self.control(old, self.claim_cmr.as_ref()),
            witness,
        }
    }
}

#[derive(Clone, Debug, serde::Serialize)]
pub struct Report {
    pub cmr: String,
    pub program_bytes: usize,
    pub witness_bytes: usize,
    pub cost_milliweight: String,
    pub budget_valid_without_padding: bool,
    pub bit_machine_extra_cells: usize,
    pub bit_machine_extra_frames: usize,
    pub transaction_weight: usize,
    pub amount_proofs_checked: bool,
}

impl Bridge {
    /// Satisfy, prune, encode, decode and execute input 0 the way a node would.
    pub fn run(&self, s: &Spend, check_amounts: bool) -> std::result::Result<Report, String> {
        let cmr = self.claim_cmr;
        let pre = |ok: bool, why: &'static str| -> std::result::Result<(), String> {
            require(ok, why).map_err(str::to_owned)
        };

        // Preconditions consensus checks before scripts run.
        pre(s.tx.input.len() == s.spent.len(), "UTXO shape")?;
        let key = XOnlyPublicKey::from_slice(&s.spent[0].script_pubkey.as_bytes()[2..])
            .map_err(|_| "state output key")?;
        pre(
            s.spent[0].script_pubkey.is_v1_p2tr()
                && s.control.verify_taproot_commitment(
                    &secp(),
                    &elements::schnorr::TweakedPublicKey::new(key),
                    &Script::from(cmr.as_ref().to_vec()),
                ),
            "control block commitment",
        )?;
        if check_amounts {
            s.tx.verify_tx_amt_proofs(&secp(), &s.spent)
                .map_err(|e| format!("Elements amount proofs: {e:?}"))?;
        }

        let env = ElementsEnv::new(
            Arc::new(s.tx.clone()),
            s.spent.iter().cloned().map(ElementsUtxo::from).collect(),
            0,
            cmr,
            s.control.clone(),
            None,
            elements::BlockHash::from_byte_array(self.params.liquid_genesis),
        );
        let map = s
            .witness
            .iter()
            .map(|(k, v)| (TemplateProgramWitness::witness_from_str(*k), v.clone()))
            .collect();
        let satisfied = self
            .claim
            .satisfy_with_env(WitnessValues::from_map(map), Some(&env))?;
        let (code, witness) = satisfied.redeem().to_vec_with_witness();
        let decoded = RedeemNode::decode::<_, _, Elements>(
            BitIter::from(code.as_slice()),
            BitIter::from(witness.as_slice()),
        )
        .map_err(|e| e.to_string())?;
        pre(decoded.cmr() == cmr, "CMR changed by encoding")?;
        BitMachine::for_program(&decoded)
            .map_err(|e| e.to_string())?
            .exec(&decoded, &env)
            .map_err(|e| e.to_string())?;

        let stack = vec![
            witness.clone(),
            code.clone(),
            cmr.as_ref().to_vec(),
            s.control.serialize(),
        ];
        let bounds = decoded.bounds();
        let mut tx = s.tx.clone();
        tx.input[0].witness.script_witness = stack.clone();
        // Input 1 is a P2WPKH fee input.
        tx.input[1].witness.script_witness = vec![vec![0; 73], vec![0; 33]];
        Ok(Report {
            cmr: cmr.to_string(),
            program_bytes: code.len(),
            witness_bytes: witness.len(),
            cost_milliweight: bounds.cost.to_string(),
            budget_valid_without_padding: bounds.cost.is_budget_valid(&stack),
            bit_machine_extra_cells: bounds.extra_cells,
            bit_machine_extra_frames: bounds.extra_frames,
            transaction_weight: tx.weight(),
            amount_proofs_checked: check_amounts,
        })
    }
}

/// Deterministic local parameters.
pub fn test_params() -> Params {
    let prevout = OutPoint::new(Txid::from_byte_array([12; 32]), 0);
    let entropy = AssetId::generate_asset_entropy(
        prevout,
        elements::issuance::ContractHash::from_byte_array([0; 32]),
    )
    .to_byte_array();
    Params {
        liquid_genesis: [13; 32],
        entropy,
        fee_asset: AssetId::from_byte_array([14; 32]),
        deposit_domain: sha(b"test-only deposit domain; BridgeDeposits.DOMAIN in deployment"),
        token_blinding: [token_blinding(entropy, 0), token_blinding(entropy, 1)],
    }
}

pub fn check_params(p: &Params) -> Result<()> {
    for bf in &p.token_blinding {
        require(
            SecretKey::from_slice(bf).is_ok(),
            "token blinding is not a valid scalar",
        )?;
    }
    require(
        p.token_blinding[0] != p.token_blinding[1],
        "token blindings must differ",
    )
}
